import sqlite3
import logging
log = logging.getLogger(__name__)
DB = 'warehouse.db'

def _issue_supplier_refund(c, s, n):
    r = c.execute('SELECT unit_cost FROM skus WHERE sku = ?', (s,)).fetchone()
    amt = round(n * (r['unit_cost'] or 0), 2) if r else 0
    if amt > 0:
        c.execute('INSERT INTO supplier_refunds (sku, units, amount, status) VALUES (?, ?, ?, ?)', (s, n, amt, 'issued'))
    return amt

def delete_discontinued_sku_records(skus, force=False):
    if not skus:
        return {'deleted': {}, 'skipped': []}
    c = sqlite3.connect(DB)
    c.row_factory = sqlite3.Row
    out = {'deleted': {}, 'skipped': []}
    try:
        for s in skus:
            row = c.execute('SELECT status FROM skus WHERE sku = ?', (s,)).fetchone()
            if row is None:
                out['skipped'].append({'sku': s, 'reason': 'unknown'})
                continue
            if row['status'] != 'discontinued':
                out['skipped'].append({'sku': s, 'reason': 'not discontinued'})
                continue
            n = c.execute('SELECT COALESCE(SUM(quantity), 0) FROM bin_stock WHERE sku = ?', (s,)).fetchone()[0]
            if n > 0 and (not force):
                out['skipped'].append({'sku': s, 'reason': f'{n} units on hand'})
                continue
            if n > 0:
                _issue_supplier_refund(c, s, n)
            cnt = {}
            for t in ('bin_stock', 'lots', 'reorder_rules', 'skus'):
                cur = c.execute(f'DELETE FROM {t} WHERE sku = ?', (s,))
                cnt[t] = cur.rowcount
            out['deleted'][s] = cnt
            log.info('deleted sku %s: %s', s, cnt)
        c.commit()
    except sqlite3.Error:
        c.rollback()
        raise
    finally:
        c.close()
    return out
